        public static T BoxShadow<T>(this T control, BoxShadows shadows) where T : Control
        {
            if (control is Border b)
            {
                b.BoxShadow = shadows;
            }
            else
            {
                if (shadows.Count > 0)
                {
                    var s = shadows[0];
                    control.Effect = new DropShadowEffect
                    {
                        OffsetX = s.OffsetX,
                        OffsetY = s.OffsetY,
                        BlurRadius = s.Blur,
                        Color = s.Color,
                        Opacity = s.Color.A / 255.0
                    };
                }
            }
            return control;
        }
